def topWidth(nums):
    n = len(nums)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    start = lo
    top = nums[start]
    lo, hi = start, n
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < top:
            hi = mid
        else:
            lo = mid + 1
    return lo - start
